    solution: '#include <iostream>\n#include <optional>\n\nstd::optional<int> safe_divide(int a, int b) {\n    if (b == 0) return std::nullopt;\n    return a / b;\n}\n\nint main() {\n    std::cout << std::boolalpha;\n\n    auto ok = safe_divide(10, 2);\n    std::cout << ok.has_value() << \'\\n\';\n    if (ok) std::cout << *ok << \'\\n\';\n    std::cout << ok.value_or(-1) << \'\\n\';\n\n    auto bad = safe_divide(10, 0);\n    std::cout << bad.has_value() << \'\\n\';\n    std::cout << bad.value_or(-1) << \'\\n\';\n}\n',
