    example: '#include <iostream>\n#include <iomanip>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <numeric>\n\nstruct Sale {\n    std::string region;\n    double amount;\n};\n\nint main() {\n    std::vector<Sale> sales{\n        {"north", 1200.50}, {"south", 890.25},\n        {"north", 450.75}, {"east", 2100.00}\n    };\n\n    double total = std::accumulate(sales.begin(), sales.end(), 0.0,\n        [](double sum, const Sale& s) { return sum + s.amount; });\n\n    auto best = std::max_element(sales.begin(), sales.end(),\n        [](const Sale& a, const Sale& b) { return a.amount < b.amount; });\n\n    std::cout << std::fixed << std::setprecision(2);\n    std::cout << "total " << total << \'\\n\';\n    std::cout << "best " << best->region << \' \' << best->amount << \'\\n\';\n    std::cout << "count " << std::count_if(sales.begin(), sales.end(),\n        [](const Sale& s) { return s.amount > 1000; }) << \'\\n\';\n}',
