    solution: '#include <iostream>\n#include <iomanip>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <numeric>\n\nclass Product {\n    std::string name;\n    double price;\n    int quantity;\npublic:\n    Product(std::string n, double p, int q)\n        : name{std::move(n)}, price{p}, quantity{q} {}\n\n    const std::string& get_name() const { return name; }\n    double get_price() const { return price; }\n    int get_quantity() const { return quantity; }\n    double value() const { return price * quantity; }\n};\n\nint main() {\n    std::vector<Product> items{\n        {"bread", 2.50, 3},\n        {"cheese", 7.40, 1},\n        {"milk", 1.20, 6},\n        {"honey", 5.90, 2}\n    };\n\n    std::sort(items.begin(), items.end(),\n              [](const Product& a, const Product& b) { return a.value() > b.value(); });\n\n    std::cout << std::fixed << std::setprecision(2);\n    for (const auto& p : items) {\n        std::cout << p.get_name() << \' \' << p.get_price() << " x "\n                  << p.get_quantity() << " = " << p.value() << \'\\n\';\n    }\n\n    double total = std::accumulate(items.begin(), items.end(), 0.0,\n        [](double sum, const Product& p) { return sum + p.value(); });\n\n    std::cout << "total " << total << \'\\n\';\n    std::cout << "over 20: " << std::count_if(items.begin(), items.end(),\n        [](const Product& p) { return p.value() > 20.0; }) << \'\\n\';\n}\n',
